def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    ones=[(r,c) for r in range(h) for c in range(w) if g[r][c]==1]
    blocked=set()
    for r,c in ones:
        best=None
        for r2,c2 in ones:
            if (r2,c2)==(r,c): continue
            if abs(r2-r)==abs(c2-c):
                dist=abs(r2-r)
                if best is None or dist<best[0]: best=(dist,r2,c2)
        if best is None: continue
        _,r2,c2=best
        dr=(r2>r)-(r2<r); dc=(c2>c)-(c2<c)
        rr,cc=r+dr,c+dc
        while 0<=rr<h and 0<=cc<w:
            v=g[rr][cc]
            if v!=4:
                if v==6: blocked.add((rr,cc))
                break
            out[rr][cc]=1
            rr+=dr; cc+=dc
    for r,c in blocked:
        for dr,dc in ((1,1),(-1,-1)):
            rr,cc=r+dr,c+dc
            while 0<=rr<h and 0<=cc<w:
                if g[rr][cc]!=4: break
                out[rr][cc]=6
                rr+=dr; cc+=dc
    return out

