from collections import Counter
def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    out=[row[:] for row in g]
    ones=[(r,c) for r in range(h) for c in range(w) if g[r][c]==1]
    emit={}  # 6 pos -> set of beam dirs
    for r,c in ones:
        best=None
        for r2,c2 in ones:
            if (r2,c2)==(r,c): continue
            if abs(r2-r)==abs(c2-c):
                dist=abs(r2-r)
                if best is None or dist<best[0]: best=(dist,r2,c2)
        if best is None: continue
        _,r2,c2=best
        dr=(r2>r)-(r2<r); dc=(c2>c)-(c2<c)
        rr,cc=r+dr,c+dc
        while 0<=rr<h and 0<=cc<w:
            v=g[rr][cc]
            if v==1: break
            if v==6: emit.setdefault((rr,cc),set()).add((dr,dc))
            else: out[rr][cc]=1
            rr+=dr; cc+=dc
    for (r,c),dirs in emit.items():
        for dr,dc in dirs:
            for edr,edc in ((dr,-dc),(-dr,dc)):
                rr,cc=r+edr,c+edc
                while 0<=rr<h and 0<=cc<w:
                    if g[rr][cc]!=bg: break
                    out[rr][cc]=6
                    rr+=edr; cc+=edc
    return out

